pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newDifficulty) internal {
        vm.assume(newDifficulty != 0);
        try c.AdjustDifficulty(newDifficulty) {} catch { return; }
        uint256 afterDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { afterDifficulty = __r; } catch { return; }
        assertTrue(afterDifficulty == newDifficulty);
    }

    function testFuzz_run(uint256 newDifficulty) public {
        _run(newDifficulty);
    }

    receive() external payable {}
}
